import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 70 When were they there?","description":"学习 过去存在句与时间介词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 70 When were they there?","description":"学习 过去存在句与时间介词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 过去存在句与时间介词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 69 The car race","link":"/life/english/new-concept/book-1/unit-03/lesson-069"},"next":{"text":"第一册：英语初阶 · Lesson 71 He's awful!","link":"/life/english/new-concept/book-1/unit-03/lesson-071"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 69 The car race","link":"/life/english/new-concept/book-1/unit-03/lesson-069"},"next":{"text":"第一册：英语初阶 · Lesson 71 He's awful!","link":"/life/english/new-concept/book-1/unit-03/lesson-071"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-03/lesson-070.md","filePath":"life/english/new-concept/book-1/unit-03/lesson-070.md"}`),r={name:"life/english/new-concept/book-1/unit-03/lesson-070.md"};function l(i,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-lesson-70-when-were-they-there" tabindex="-1">第一册：英语初阶 · Lesson 70 When were they there? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-70-when-were-they-there" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 70 When were they there?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元 3</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-069">配套课 Lesson 69</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>描述过去一场活动的时间与场景 本课要掌握过去存在句与时间介词，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>race</td><td>/reɪs/</td><td>n.</td><td>比赛</td><td>a car race</td></tr><tr><td>crowd</td><td>/kraʊd/</td><td>n.</td><td>人群</td><td>a large crowd</td></tr><tr><td>exciting</td><td>/ɪkˈsaɪtɪŋ/</td><td>adj.</td><td>令人兴奋的</td><td>an exciting event</td></tr><tr><td>winner</td><td>/ˈwɪnə/</td><td>n.</td><td>获胜者</td><td>the race winner</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>there were — 过去有多个对象</li><li>on Sunday — 在星期日</li></ul><h2 id="语法讲解-过去存在句与时间介词" tabindex="-1">语法讲解：过去存在句与时间介词 <a class="header-anchor" href="#语法讲解-过去存在句与时间介词" aria-label="Permalink to &quot;语法讲解：过去存在句与时间介词&quot;">​</a></h2><p>there was/there were 介绍过去存在的事物，be 的数取决于后面的名词。There were many people 强调过去人多。on 用具体某天或日期，in 用月份年份等，at 用钟点；含 last、next、every 的时间短语通常不再加介词，如 last Sunday。when 询问时间，不等于 where。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The final was on Sunday afternoon.</p></blockquote><p>决赛在星期日下午。</p><p>The final 是单数主语，用 was；on Sunday afternoon 是具体某天下午，所以使用 on。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>具体某天下午用 on Sunday afternoon；不是 in Sunday afternoon。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“The final was on Sunday afternoon.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The final was on Sunday afternoon. There were hundreds of people at the race.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“描述过去一场活动的时间与场景”写两至三句，再读给同伴听。至少使用一次过去存在句与时间介词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>The final 是单数主语，用 was；on Sunday afternoon 是具体某天下午，所以使用 on。 There were 引出过去存在的人群；hundreds of people 是复数，at the race 表现场。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补介词：___ Sunday afternoon.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> on</p><p><strong>解析：</strong> 按本课规则判断：there was/there were 介绍过去存在的事物，be 的数取决于后面的名词。There were many people 强调过去人多。on 用具体某天或日期，in 用月份年份等，at 用钟点；含 last、next、every 的时间短语通常不再加介词，如 last Sunday。when 询问时间，不等于 where。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“决赛在星期日下午。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The final was on Sunday afternoon.</p><p><strong>解析：</strong> The final 是单数主语，用 was；on Sunday afternoon 是具体某天下午，所以使用 on。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：There were hundreds of people at the race.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 比赛现场有数百人。</p><p><strong>解析：</strong> There were 引出过去存在的人群；hundreds of people 是复数，at the race 表现场。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去存在句与时间介词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-03/lesson-069">上一课</a> · <a href="/life/english/new-concept/book-1/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-03/lesson-071">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(r,[["render",l]]);export{u as __pageData,f as default};
